const PLACEHOLDER_PREFIXES = ['__SET_', '__REQUIRED_', '__OVERRIDE_'] as const;

const isDisabledFlag = (value: string): boolean => {
  const normalized = value.trim().toLowerCase();
  return normalized === 'false' || normalized === '0';
};

const isPlaceholderValue = (value: string | undefined) =>
  typeof value === 'string' &&
  PLACEHOLDER_PREFIXES.some((prefix) => value.startsWith(prefix));

const readEnvValue = (env: NodeJS.ProcessEnv, key: string) => {
  const value = env[key];
  return typeof value === 'string' ? value.trim() : '';
};

const hasAnyValue = (env: NodeJS.ProcessEnv, keys: readonly string[]) =>
  keys.some((key) => readEnvValue(env, key).length > 0);

const hasAllValues = (env: NodeJS.ProcessEnv, keys: readonly string[]) =>
  keys.every((key) => readEnvValue(env, key).length > 0);

const isJsonObjectValue = (value: string) => {
  try {
    const parsed: unknown = JSON.parse(value);
    return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed);
  } catch {
    return false;
  }
};

const isRuntimeEnvValueInvalid = (key: string, value: string) => {
  switch (key) {
    case 'IAM_PII_KEYRING_JSON':
      return !isJsonObjectValue(value);
    default:
      return false;
  }
};

export const parseRuntimeProfile = (value: string | undefined): RuntimeProfile | null => {
  if (value === undefined) {
    return null;
  }

  const normalized = value.trim();
  return (RUNTIME_PROFILES as readonly string[]).includes(normalized)
    ? (normalized as RuntimeProfile)
    : null;
};

import { readFileSync } from 'node:fs';

const isWrappedInQuote = (rawValue: string, quote: '"' | "'") =>
  rawValue.startsWith(quote) && rawValue.endsWith(quote);

const unquoteVarsValue = (rawValue: string): string => {
  if (isWrappedInQuote(rawValue, '"') || isWrappedInQuote(rawValue, "'")) {
    return rawValue.slice(1, -1);
  }

  return rawValue;
};

const parseVarsLine = (rawLine: string): readonly [string, string] | null => {
  const line = rawLine.trim();
  if (line.length === 0 || line.startsWith('#')) {
    return null;
  }

  const separatorIndex = line.indexOf('=');
  if (separatorIndex < 1) {
    return null;
  }

  const key = line.slice(0, separatorIndex).trim();
  const value = unquoteVarsValue(line.slice(separatorIndex + 1).trim());
  return [key, value];
};

export const parseVarsFile = (filePath: string): Record<string, string> => {
  const parsed: Record<string, string> = {};
  const content = readFileSync(filePath, 'utf8');

  for (const rawLine of content.split(/\r?\n/u)) {
    const parsedLine = parseVarsLine(rawLine);
    if (!parsedLine) {
      continue;
    }

    const [key, value] = parsedLine;
    parsed[key] = value;
  }

  return parsed;
};
